import{_ as t,o,c as r,a2 as a}from"./chunks/framework.il0noOp3.js";const h=JSON.parse('{"title":"Verification report — §3c \\"Minimum permissions to read and collect\\"","description":"","frontmatter":{},"headers":[],"relativePath":"audits/_verification-report.md","filePath":"audits/_verification-report.md"}'),s={name:"audits/_verification-report.md"};function i(n,e,c,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="verification-report-—-§3c-minimum-permissions-to-read-and-collect" tabindex="-1">Verification report — §3c &quot;Minimum permissions to read and collect&quot; <a class="header-anchor" href="#verification-report-—-§3c-minimum-permissions-to-read-and-collect" aria-label="Permalink to &quot;Verification report — §3c &quot;Minimum permissions to read and collect&quot;&quot;">​</a></h1><p>Adversarial fact-check against Microsoft Learn. Every role definition below was pulled in full (<code>microsoft_docs_fetch</code>), not from search excerpts.</p><hr><h2 id="verdict" tabindex="-1">Verdict <a class="header-anchor" href="#verdict" aria-label="Permalink to &quot;Verdict&quot;">​</a></h2><p><strong>Not trustworthy as written.</strong> The headline conclusion — <em>Azure RBAC <code>Reader</code> at root MG covers every ARM collector</em> — is correct and now solidly proven. But the section contains <strong>one error that changes what a customer would grant</strong> (CrossTenantAccess), <strong>one load-bearing citation that says the opposite of what it is cited for</strong> (Cost Management), <strong>three false &quot;strict subset&quot; claims about the redundant roles</strong>, and <strong>an internal contradiction between the §3c prose and the document&#39;s own Table B</strong>. Roughly 8 defects, 2 of them serious.</p><hr><h2 id="errors-found" tabindex="-1">Errors found <a class="header-anchor" href="#errors-found" aria-label="Permalink to &quot;Errors found&quot;">​</a></h2><h3 id="e1-—-serious-directory-readers-entra-security-reader-covers-every-entra-collector-scout-has-is-false-and-the-document-contradicts-itself" tabindex="-1">E1 — SERIOUS. &quot;<code>Directory Readers</code> + Entra <code>Security Reader</code> covers every Entra collector Scout has&quot; is false, and the document contradicts itself <a class="header-anchor" href="#e1-—-serious-directory-readers-entra-security-reader-covers-every-entra-collector-scout-has-is-false-and-the-document-contradicts-itself" aria-label="Permalink to &quot;E1 — SERIOUS. &quot;`Directory Readers` + Entra `Security Reader` covers every Entra collector Scout has&quot; is false, and the document contradicts itself&quot;">​</a></h3><p>Line 561 states this flatly. Line 1009 (Table B, same document) says CrossTenantAccess is <strong>Unverified</strong> and may need Global Reader. Both cannot be true.</p><p>The correct fact: <strong>neither recommended role grants any read on the cross-tenant access policy.</strong> The complete action lists are:</p><ul><li><code>Directory Readers</code> — no <code>crossTenantAccessPolicy</code> entry of any kind.</li><li>Entra <code>Security Reader</code> — only two entries, both for <em>templates</em>: <code>crossTenantAccessPolicy/partners/templates/multiTenantOrganizationIdentitySynchronization/standard/read</code> and <code>.../multiTenantOrganizationPartnerConfiguration/standard/read</code>.</li></ul><p>Scout calls <code>/v1.0/policies/crossTenantAccessPolicy/partners</code> — the live partner configuration, not a template. Neither role covers it.</p><p>Source: <a href="https://learn.microsoft.com/entra/identity/role-based-access-control/permissions-reference" target="_blank" rel="noreferrer">https://learn.microsoft.com/entra/identity/role-based-access-control/permissions-reference</a> (sections <code>## Directory Readers</code>, <code>## Security Reader</code>).</p><p><strong>Severity: changes the grant.</strong> A customer following the §3c recommendation gets a silently empty CrossTenantAccess worksheet. Either add a third role or state the gap in §3c, not only in Table B.</p><h3 id="e2-—-serious-table-b-s-supporting-claim-for-that-row-is-also-wrong" tabindex="-1">E2 — SERIOUS. Table B&#39;s supporting claim for that row is also wrong <a class="header-anchor" href="#e2-—-serious-table-b-s-supporting-claim-for-that-row-is-also-wrong" aria-label="Permalink to &quot;E2 — SERIOUS. Table B&#39;s supporting claim for that row is also wrong&quot;">​</a></h3><p>Line 1009: <em>&quot;there is <strong>no</strong> action for the <code>partners</code> collection itself in any role definition.&quot;</em></p><p>False. <code>microsoft.directory/crossTenantAccessPolicy/partners/standard/read</code> exists and is held by <strong>Global Administrator, Global Reader, Security Administrator, Teams Administrator, and Tenant Governance Administrator</strong>. The narrower <code>crossTenantAccessPolicy/default/standard/read</code> and <code>crossTenantAccessPolicy/standard/read</code> likewise exist.</p><p>Same URL as E1. This is the same failure mode as the previously-confirmed <code>namedLocations</code> error — an absence asserted from an incomplete read.</p><p><strong>Severity: material.</strong> The fix is not &quot;fall back to Global Reader&quot; — <code>Security Administrator</code> and <code>Tenant Governance Administrator</code> also carry it, and are worth evaluating before reaching for the privileged read-everything role.</p><h3 id="e3-—-serious-the-cost-management-citation-contradicts-the-claim-it-is-attached-to" tabindex="-1">E3 — SERIOUS. The Cost Management citation contradicts the claim it is attached to <a class="header-anchor" href="#e3-—-serious-the-cost-management-citation-contradicts-the-claim-it-is-attached-to" aria-label="Permalink to &quot;E3 — SERIOUS. The Cost Management citation contradicts the claim it is attached to&quot;">​</a></h3><p>Line 691 cites <a href="https://learn.microsoft.com/azure/cost-management-billing/costs/assign-access-acm-data" target="_blank" rel="noreferrer">Assign access to Cost Management data</a> as evidence that <code>Reader</code> suffices and <em>&quot;Cost Management Reader is redundant.&quot;</em></p><p>That page says the opposite. Repeatedly:</p><blockquote><p>&quot;Access to a subscription requires at least the <strong>Cost Management Reader</strong> (or Contributor) permission.&quot; — and the same sentence for resource-group and management-group scope. Its EA scope table lists &quot;Cost Management Reader (or Contributor)&quot; as the <em>Required access to view data</em> for management group, subscription, and resource group. <code>Reader</code> is never named.</p></blockquote><p>The <em>other</em> citation — the role-behaviour table in <a href="https://learn.microsoft.com/azure/cost-management-billing/costs/understand-work-scopes#azure-rbac-scopes" target="_blank" rel="noreferrer">Understand and work with scopes</a> — <strong>does</strong> support the claim: <code>Reader</code> = &quot;Read only&quot; on <em>Cost Analysis / Forecast / Query / Cost Details API</em>. So Microsoft&#39;s own two pages conflict.</p><p><strong>Severity: the conclusion is probably right, the evidence as presented is not.</strong> Cite only <code>understand-work-scopes</code>, drop <code>assign-access-acm-data</code>, and say plainly that a second Microsoft page contradicts it.</p><h3 id="e4-—-azure-rbac-security-reader-is-a-strict-subset-of-read-is-false" tabindex="-1">E4 — &quot;Azure RBAC <code>Security Reader</code> is a strict subset of <code>*/read</code>&quot; is false <a class="header-anchor" href="#e4-—-azure-rbac-security-reader-is-a-strict-subset-of-read-is-false" aria-label="Permalink to &quot;E4 — &quot;Azure RBAC `Security Reader` is a strict subset of `*/read`&quot; is false&quot;">​</a></h3><p>Line 693. The full definition (role id <code>39bc4728-0917-49c7-9d2c-d95423bc2eb4</code>) contains <strong>five <code>/action</code> permissions</strong>, none of which is inside <code>*/read</code>:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Microsoft.Security/iotDefenderSettings/packageDownloads/action</span></span>\n<span class="line"><span>Microsoft.Security/iotDefenderSettings/downloadManagerActivation/action</span></span>\n<span class="line"><span>Microsoft.Security/iotSensors/downloadResetPassword/action</span></span>\n<span class="line"><span>Microsoft.IoTSecurity/defenderSettings/packageDownloads/action</span></span>\n<span class="line"><span>Microsoft.IoTSecurity/defenderSettings/downloadManagerActivation/action</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>Source: <a href="https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/security#security-reader" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/security#security-reader</a></p><p>Note <code>iotSensors/downloadResetPassword/action</code> — downloads a password-reset file. The document flags Monitoring Reader for granting a write while missing that Security Reader grants five.</p><p><strong>Severity: reasoning, not outcome.</strong> The role is still redundant <em>for Scout</em> (line 1120 in Table C&#39;s preamble gets this right). But &quot;strict subset&quot; is wrong and would fail review.</p><h3 id="e5-—-monitoring-reader-is-a-strict-subset-of-read-is-false-—-it-is-a-strict-superset" tabindex="-1">E5 — &quot;Monitoring Reader is a strict subset of <code>*/read</code>&quot; is false — it is a strict <strong>superset</strong> <a class="header-anchor" href="#e5-—-monitoring-reader-is-a-strict-subset-of-read-is-false-—-it-is-a-strict-superset" aria-label="Permalink to &quot;E5 — &quot;Monitoring Reader is a strict subset of `*/read`&quot; is false — it is a strict **superset**&quot;">​</a></h3><p>Same line 693. Monitoring Reader (<code>43d0d8ad-25c7-4714-9337-8ba259a9fe05</code>) is:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*/read</span></span>\n<span class="line"><span>Microsoft.OperationalInsights/workspaces/search/action</span></span>\n<span class="line"><span>Microsoft.Support/*</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>It contains all of Reader plus two more. The document also omits <code>OperationalInsights/workspaces/search/action</code> when listing what it adds.</p><p>Source: <a href="https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/monitor#monitoring-reader" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/monitor#monitoring-reader</a></p><h3 id="e6-—-cost-management-reader-also-grants-microsoft-support-and-the-document-does-not-say-so" tabindex="-1">E6 — Cost Management Reader also grants <code>Microsoft.Support/*</code>, and the document does not say so <a class="header-anchor" href="#e6-—-cost-management-reader-also-grants-microsoft-support-and-the-document-does-not-say-so" aria-label="Permalink to &quot;E6 — Cost Management Reader also grants `Microsoft.Support/*`, and the document does not say so&quot;">​</a></h3><p>Line 466 singles out Monitoring Reader for the <code>Microsoft.Support/*</code> ticket-creation write. Cost Management Reader (<code>72fafb9e-0641-4937-9268-a91bfd8191a3</code>) carries the identical <code>Microsoft.Support/*</code>. So does <code>Billing Reader</code>. If the write is worth flagging on one role it is worth flagging on all three — otherwise a reader concludes Cost Management Reader is write-free.</p><p>Source: <a href="https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/management-and-governance#cost-management-reader" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/management-and-governance#cost-management-reader</a></p><h3 id="e7-—-§3c-attributes-directoryroles-to-entra-security-reader-it-is-covered-by-directory-readers" tabindex="-1">E7 — §3c attributes <code>DirectoryRoles</code> to Entra <code>Security Reader</code>; it is covered by <code>Directory Readers</code> <a class="header-anchor" href="#e7-—-§3c-attributes-directoryroles-to-entra-security-reader-it-is-covered-by-directory-readers" aria-label="Permalink to &quot;E7 — §3c attributes `DirectoryRoles` to Entra `Security Reader`; it is covered by `Directory Readers`&quot;">​</a></h3><p>Line 513 lists <code>DirectoryRoles</code> among what Security Reader unlocks. Security Reader&#39;s action list contains <strong>no</strong> <code>directoryRoles/</code> entry at all. <code>Directory Readers</code> has <code>directoryRoles/standard/read</code>, <code>/members/read</code>, <code>/eligibleMembers/read</code>. Table B line 1000 gets this right; §3c does not.</p><p><strong>Severity: low</strong>, but it inflates the apparent necessity of the privileged role.</p><h3 id="e8-—-mca-gate-wrong-role-named" tabindex="-1">E8 — MCA gate: wrong role named <a class="header-anchor" href="#e8-—-mca-gate-wrong-role-named" aria-label="Permalink to &quot;E8 — MCA gate: wrong role named&quot;">​</a></h3><p>Line 625: <em>&quot;Only an Enterprise Administrator (EA) or <strong>Billing account owner</strong> (MCA) can change these.&quot;</em> For MCA the setting sits on the <strong>billing profile</strong> and Microsoft states: <em>&quot;You must have <strong>Billing Profile Owners</strong> permission to enable the setting.&quot;</em></p><p>Source: <a href="https://learn.microsoft.com/azure/cost-management-billing/costs/assign-access-acm-data#enable-mca-access-to-costs" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cost-management-billing/costs/assign-access-acm-data#enable-mca-access-to-costs</a></p><p>Also minor: the MCA setting&#39;s current name is <strong>&quot;Azure charges&quot;</strong>; the document uses the older &quot;Allow Azure subscription users to view and optimize costs&quot;.</p><h3 id="e9-—-verified-column-contradicts-the-source-column-on-at-least-7-rows" tabindex="-1">E9 — <code>Verified</code> column contradicts the <code>Source</code> column on at least 7 rows <a class="header-anchor" href="#e9-—-verified-column-contradicts-the-source-column-on-at-least-7-rows" aria-label="Permalink to &quot;E9 — `Verified` column contradicts the `Source` column on at least 7 rows&quot;">​</a></h3><p><code>Doc</code> is defined at line 684 as &quot;confirmed against Microsoft Learn&quot;. These rows say <code>Doc</code> while their own Source says otherwise:</p><table tabindex="0"><thead><tr><th>Row</th><th>Verified</th><th>Source</th></tr></thead><tbody><tr><td>CloudServices</td><td>Doc</td><td><strong>NOT FOUND</strong></td></tr><tr><td>ArcDataControllers</td><td>Doc</td><td><strong>NOT FOUND</strong></td></tr><tr><td>ArcSQLManagedInstances</td><td>Doc</td><td><strong>NOT FOUND</strong></td></tr><tr><td>ArcSQLServers</td><td>Doc</td><td>&quot;not on any <code>permissions/</code> provider page&quot;</td></tr><tr><td>NATGateway</td><td>Doc</td><td><strong>NOT FOUND</strong></td></tr><tr><td>AVDApplicationGroups</td><td>Doc</td><td><code>n/a</code></td></tr><tr><td>AVDApplications</td><td>Doc</td><td><code>n/a</code></td></tr><tr><td>AutomationAccounts</td><td>Doc</td><td><code>n/a</code></td></tr></tbody></table><p>Either the row is documented or it is not. The <code>n/a</code> rows are also uncounted in the 133/142 citation-coverage arithmetic, so 93.7% is not reproducible from the table.</p><hr><h2 id="claims-confirmed" tabindex="-1">Claims confirmed <a class="header-anchor" href="#claims-confirmed" aria-label="Permalink to &quot;Claims confirmed&quot;">​</a></h2><ol><li><p><strong><code>Reader</code> = <code>Actions: [&quot;*/read&quot;]</code>, <code>notActions: []</code>, <code>dataActions: []</code>, <code>notDataActions: []</code>.</strong> Verified against the JSON in the role definition itself, id <code>acdd72a7-3385-48ef-bd42-f606fba81ae7</code>. <code>NotActions</code> is genuinely empty. <a href="https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/general" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/built-in-roles/general</a></p></li><li><p><strong>Monitoring Reader grants <code>Microsoft.Support/*</code> — ticket creation, a write.</strong> Confirmed verbatim (&quot;Create and update a support ticket&quot;). Claim 3 stands.</p></li><li><p><strong>All five Entra <code>Security Reader</code> actions Scout depends on are present.</strong> Individually checked in the full definition: <code>conditionalAccessPolicies/standard/read</code>, <code>namedLocations/standard/read</code>, <code>identityProtection/allProperties/read</code>, <code>privilegedIdentityManagement/allProperties/read</code>, <code>policies/standard/read</code>. Also present: <code>authorizationPolicy/standard/read</code> (the action Table B actually needs for SecurityPolicies), <code>signInReports/*</code>, <code>auditLogs/*</code>. The earlier namedLocations correction is itself correct.</p></li><li><p><strong><code>Directory Readers</code> has zero Conditional Access actions.</strong> Confirmed — the complete 56-action list contains no <code>conditionalAccessPolicies</code> entry. Claim 6 stands.</p></li><li><p><strong><code>Global Reader</code> is a privileged role.</strong> Confirmed — carries the privileged label and the sentence &quot;This is a privileged role&quot;. Claim 9 stands. <em>Not flagged by the document but true and relevant:</em> <strong>Entra <code>Security Reader</code> is also labelled privileged</strong>, and includes <code>microsoft.directory/bitlockerKeys/key/read</code> — itself individually privileged. The table marks it &quot;Privileged? Yes&quot; but never mentions BitLocker recovery-key read in the &quot;Covers&quot; column. Worth stating; it is the strongest argument a security reviewer will make.</p></li><li><p><strong><code>Reports Reader</code> is not privileged</strong> and grants nothing Scout uses (audit logs, sign-in reports, provisioning logs only). Confirmed.</p></li><li><p><strong>EA/MCA billing claims (claim 10) — all confirmed.</strong></p><ul><li>&quot;Enterprise Administrator (read only)&quot; and &quot;Department Administrator (read only)&quot; are real role names in the usage-and-costs-access table. <a href="https://learn.microsoft.com/azure/cost-management-billing/manage/understand-ea-roles" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cost-management-billing/manage/understand-ea-roles</a></li><li>Both <strong>AO view charges</strong> and <strong>DA view charges</strong> gates exist and are independent.</li><li><em>&quot;If DA view charges option is disabled, department users can&#39;t see costs at any level, even if they&#39;re an account or subscription owner&quot;</em> — verbatim.</li><li>The Billing Reader quote is verbatim from <a href="https://learn.microsoft.com/azure/cost-management-billing/manage/manage-billing-access#give-read-only-access-to-billing" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/cost-management-billing/manage/manage-billing-access#give-read-only-access-to-billing</a>, as is &quot;The Billing Reader feature is in preview, and doesn&#39;t yet support nonglobal clouds.&quot;</li><li>&quot;Although RBAC scopes are bound to a single directory, EA billing scopes aren&#39;t&quot; — verbatim.</li><li>MCA read-only roles (Billing account / Billing profile / Invoice section Reader) — supported.</li></ul></li><li><p><strong><code>Microsoft.CostManagement/query/read</code> and <code>/action</code> both exist</strong>, as do <code>policyStates/queryResults/{read,action}</code> and <code>policyStates/summarize/{read,action}</code>. The document&#39;s statement of the ambiguity is accurate; its resolution is not (see below).</p></li></ol><hr><h2 id="claims-that-could-not-be-verified-from-documentation" tabindex="-1">Claims that could not be verified from documentation <a class="header-anchor" href="#claims-that-could-not-be-verified-from-documentation" aria-label="Permalink to &quot;Claims that could not be verified from documentation&quot;">​</a></h2><h3 id="claim-4-—-does-post-query-authorize-on-query-read-or-query-action" tabindex="-1">Claim 4 — does POST <code>/query</code> authorize on <code>query/read</code> or <code>query/action</code>? <a class="header-anchor" href="#claim-4-—-does-post-query-authorize-on-query-read-or-query-action" aria-label="Permalink to &quot;Claim 4 — does POST `/query` authorize on `query/read` or `query/action`?&quot;">​</a></h3><p><strong>Unresolvable from Microsoft&#39;s docs directly</strong>, but the strongest available inference favours <code>/read</code>, and the document&#39;s conclusion is probably right for the wrong reason:</p><ul><li><code>Cost Management Reader</code>&#39;s only CostManagement grant is <code>Microsoft.CostManagement/*/read</code>. It has <strong>no</strong> <code>query/action</code>. Microsoft&#39;s capability table says it can &quot;View cost data (Cost Analysis, Forecast, etc.)&quot;. Cost Analysis is the Query API. Therefore the enforced permission must be <code>query/read</code> — and <code>Reader</code>&#39;s <code>*/read</code> is a superset of <code>CostManagement/*/read</code>.</li><li>Direct precedent that ARM POSTs are routinely gated on <code>/read</code>: <code>Microsoft.ResourceGraph/resources/read</code> — <em>&quot;Submits a query on resources&quot;</em> — is the permission for the ARG POST, and Microsoft states explicitly for another operation: <em>&quot;This <strong>read</strong> permission, not <code>setAzureNetworkManagerConfiguration/action</code>, is required to call Set Azure Network Manager Configuration.&quot;</em> (<a href="https://learn.microsoft.com/azure/role-based-access-control/permissions/networking#microsoftnetwork" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/permissions/networking#microsoftnetwork</a>)</li></ul><p><strong>But this is an inference, not documentation</strong>, and it is contradicted by the <code>assign-access-acm-data</code> page (E3). Grade it <code>Untested</code>, not <code>Doc</code>.</p><h3 id="claim-5-—-policy-insights-read-vs-action" tabindex="-1">Claim 5 — Policy Insights <code>/read</code> vs <code>/action</code> <a class="header-anchor" href="#claim-5-—-policy-insights-read-vs-action" aria-label="Permalink to &quot;Claim 5 — Policy Insights `/read` vs `/action`&quot;">​</a></h3><p><strong>Genuinely unresolved.</strong> Both variants exist. The document asserts &quot;the <code>/action</code> variants belong to writer roles&quot; (line 467) — that is not supported. Counter-evidence: <strong>App Compliance Automation Administrator</strong>, a role whose job is reading compliance state, holds <code>policyStates/queryResults/action</code>, <em>not</em> <code>/read</code>. That is exactly a role reaching for the <code>/action</code> variant to query. No page states which one a POST to <code>policyStates/latest/queryResults</code> enforces. Grade <code>Untested</code>.</p><h3 id="the-arg-permission-is-missing-from-the-tables-entirely" tabindex="-1">The ARG permission is missing from the tables entirely <a class="header-anchor" href="#the-arg-permission-is-missing-from-the-tables-entirely" aria-label="Permalink to &quot;The ARG permission is missing from the tables entirely&quot;">​</a></h3><p>Every class-A row (~130 of 154 collectors) reaches Azure through Azure Resource Graph, yet no row lists <code>Microsoft.ResourceGraph/resources/read</code> in its <code>Minimum permission</code> column. <code>Reader</code> covers it, so the conclusion is unaffected — but the tables&#39; stated minimum permission is incomplete for the majority of collectors. Confirmed the action exists and is a <code>/read</code>: <a href="https://learn.microsoft.com/azure/role-based-access-control/permissions/management-and-governance#microsoftresourcegraph" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/role-based-access-control/permissions/management-and-governance#microsoftresourcegraph</a> plus <em>&quot;you must have appropriate rights ... with at least <code>read</code> access to the resources you want to query&quot;</em> (<a href="https://learn.microsoft.com/azure/governance/resource-graph/overview#permissions-in-azure-resource-graph" target="_blank" rel="noreferrer">https://learn.microsoft.com/azure/governance/resource-graph/overview#permissions-in-azure-resource-graph</a>).</p><h3 id="claim-11-s-premise-restated" tabindex="-1">Claim 11&#39;s premise, restated <a class="header-anchor" href="#claim-11-s-premise-restated" aria-label="Permalink to &quot;Claim 11&#39;s premise, restated&quot;">​</a></h3><p>The document is honest that nothing has been run against a Reader-only principal, and the &quot;probable, not proven&quot; paragraph (lines 641-649) is fair. That framing is fine. The defects above are all in things that <em>are</em> documentable and were documented wrongly.</p><hr><h2 id="spot-check-results" tabindex="-1">Spot-check results <a class="header-anchor" href="#spot-check-results" aria-label="Permalink to &quot;Spot-check results&quot;">​</a></h2><h3 id="source-anchors-claim-12-—-15-sampled-13-correct" tabindex="-1">Source anchors (claim 12) — 15 sampled, 13 correct <a class="header-anchor" href="#source-anchors-claim-12-—-15-sampled-13-correct" aria-label="Permalink to &quot;Source anchors (claim 12) — 15 sampled, 13 correct&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Row</th><th>Anchor claimed</th><th>Result</th></tr></thead><tbody><tr><td>AIFoundryHubs / MachineLearning</td><td><code>permissions/ai-machine-learning#microsoftmachinelearningservices</code></td><td>✅</td></tr><tr><td>AzureAI + 12 Cognitive rows</td><td><code>permissions/ai-machine-learning#microsoftcognitiveservices</code></td><td>✅</td></tr><tr><td>Streamanalytics</td><td><code>permissions/internet-of-things#microsoftstreamanalytics</code></td><td>✅ provider genuinely on the IoT page; action is <code>streamingjobs/Read</code> (case differs, immaterial)</td></tr><tr><td>ContainerApp / ContainerAppEnv</td><td><code>permissions/compute#microsoftapp</code></td><td>✅ <code>microsoft.app</code> is on the Compute page</td></tr><tr><td>AVD / AVDSessionHosts / AVDScalingPlans / AVDWorkspaces</td><td><code>permissions/compute#microsoftdesktopvirtualization</code></td><td>✅ <code>hostpools/read</code>, <code>workspaces/read</code> present</td></tr><tr><td>MariaDB</td><td><code>permissions/databases#microsoftdbformariadb</code></td><td>✅ provider page exists</td></tr><tr><td>NATGateway</td><td><strong>NOT FOUND</strong></td><td>✅ correctly flagged — page lists only <code>natGateways/join/action</code> and <code>natGateways/providers/Microsoft.Insights/metricDefinitions/read</code></td></tr><tr><td>PolicyComplianceStates</td><td><code>permissions/management-and-governance#microsoftpolicyinsights</code></td><td>✅ anchor right, but <code>/read</code> vs <code>/action</code> unresolved (see above)</td></tr><tr><td>VirtualMachine (cost leg)</td><td><code>permissions/management-and-governance#microsoftcostmanagement</code></td><td>✅ anchor right, <code>query/read</code> present</td></tr><tr><td>SupportTickets</td><td><code>permissions/general#microsoftsupport</code></td><td>✅</td></tr><tr><td>DefenderAlerts/Assessments/Pricing/SecureScore</td><td><code>permissions/security#microsoftsecurity</code></td><td>✅</td></tr><tr><td>AVDApplicationGroups</td><td><code>n/a</code></td><td>❌ marked <code>Verified: Doc</code> with no citation (E9)</td></tr><tr><td>AVDApplications</td><td><code>n/a</code></td><td>❌ same</td></tr><tr><td>AutomationAccounts</td><td><code>n/a</code></td><td>❌ same</td></tr><tr><td>CloudServices</td><td>NOT FOUND but <code>Verified: Doc</code></td><td>❌ (E9)</td></tr></tbody></table><p>No anchor was found pointing at a page that does not contain the claimed action. The citation <em>targets</em> are sound; the <code>Verified</code> <em>grades</em> are not.</p><h3 id="the-9-not-found-rows-claim-13-—-spot-checked-3-all-genuine" tabindex="-1">The 9 <code>NOT FOUND</code> rows (claim 13) — spot-checked 3, all genuine <a class="header-anchor" href="#the-9-not-found-rows-claim-13-—-spot-checked-3-all-genuine" aria-label="Permalink to &quot;The 9 `NOT FOUND` rows (claim 13) — spot-checked 3, all genuine&quot;">​</a></h3><ul><li><strong><code>Microsoft.Network/natGateways/read</code></strong> — genuinely absent. The Microsoft.Network table jumps from <code>masterCustomIpPrefixes/delete</code> straight to <code>natGateways/join/action</code>. The document&#39;s reading is correct and its conclusion (&quot;real type, undocumented action, <code>*/read</code> covers it&quot;) is the right call.</li><li><strong><code>Microsoft.DBforPostgreSQL/servers</code></strong> — correct; only <code>flexibleServers</code> is documented. Single Server is retired. <em>Adjacent observation the document does not make:</em> Azure Database for <strong>MariaDB</strong> was also retired, so the <code>MariaDB</code> collector is likely in the same state as <code>POSTGRE</code> even though its provider page still exists. Worth checking before the next revision.</li><li><strong><code>Microsoft.ResourceGraph</code></strong> — <em>not</em> in the NOT FOUND list because it is not in the tables at all. It is fully documented and should be added rather than being an unlisted gap.</li></ul><h3 id="internal-consistency" tabindex="-1">Internal consistency <a class="header-anchor" href="#internal-consistency" aria-label="Permalink to &quot;Internal consistency&quot;">​</a></h3><p>Three places in §3c contradict Table B or Table C&#39;s preamble: line 561 vs line 1009 (E1), line 513 vs line 1000 (E7), line 693 vs line 1120 (E4). §3c&#39;s prose is consistently the less careful of the two.</p><hr><h2 id="recommended-fixes-in-priority-order" tabindex="-1">Recommended fixes, in priority order <a class="header-anchor" href="#recommended-fixes-in-priority-order" aria-label="Permalink to &quot;Recommended fixes, in priority order&quot;">​</a></h2><ol><li>Rewrite line 561. <code>Directory Readers</code> + Entra <code>Security Reader</code> covers <strong>14 of 15</strong> Entra collectors. CrossTenantAccess needs a role carrying <code>microsoft.directory/crossTenantAccessPolicy/partners/standard/read</code> — Security Administrator, Tenant Governance Administrator, or Global Reader.</li><li>Delete the &quot;no action for the <code>partners</code> collection in any role definition&quot; sentence at line 1009; it is false.</li><li>Drop <code>assign-access-acm-data</code> as a citation for Cost Management; keep only the role-behaviour table, and note the conflict.</li><li>Replace &quot;strict subsets of <code>*/read</code>&quot; (line 693) with the accurate statement: both roles grant non-read actions; neither grants anything Scout calls.</li><li>Add <code>Microsoft.Support/*</code> to the Cost Management Reader description, or drop the callout from Monitoring Reader for consistency.</li><li>Downgrade the Cost Management and Policy Insights POST rows from <code>Doc</code> to <code>Untested</code>.</li><li>Fix the 8 rows where <code>Verified: Doc</code> sits beside <code>NOT FOUND</code> or <code>n/a</code>, and recompute 133/142.</li><li>Fix <code>DirectoryRoles</code> attribution (line 513) and the MCA gate role name (line 625).</li><li>Add <code>Microsoft.ResourceGraph/resources/read</code> to the class-A rows.</li><li>Mention that Entra <code>Security Reader</code> includes <code>bitlockerKeys/key/read</code> before someone else does.</li></ol>',77)])])}const p=t(s,[["render",i]]);export{h as __pageData,p as default};
